function macroStat(name,used,target,unit){const pct=target?Math.min(100,used/target*100):0,diff=used-target;return `<div class="logrow"><div><b>${name}</b><div class="macrobar" style="width:150px"><i style="width:${pct}%"></i></div></div><div class="macros ${diff>0?'over':''}"><b>${Math.round(used)} / ${target||0} ${unit}</b><br>${diff>0?'+':''}${Math.round(diff)} ${unit}</div></div>`}
