async function weeklyMeals(ws){const {data}=await db.from('weekly_meals').select('*,recipes(*,recipe_ingredients(*,foods(*)))').eq('week_start',ws).order('slot_number');return data||[]}
async function rebuildGroceries(ws,meals){const s=await session(),agg={};meals.forEach(w=>{const r=w.recipes;(r?.recipe_ingredients||[]).forEach(i=>{const id=i.food_id;agg[id]=(agg[id]||0)+Number(i.quantity_g)*Number(w.portion||1)})});await db.from('grocery_items').delete().eq('user_id',s.user.id).eq('week_start',ws);const rows=Object.entries(agg).map(([food_id,quantity_g])=>({user_id:s.user.id,week_start:ws,food_id:Number(food_id),quantity_g}));if(rows.length)await db.from('grocery_items').insert(rows)}
function fitScore(r,target){const m=recipeMacros(r);return Math.abs(m.calories-target.calories)/Math.max(target.calories,1)*2+Math.abs(m.protein-target.protein)/Math.max(target.protein,1)+Math.max(0,m.carbs-target.carbs)/Math.max(target.carbs,1)}
async function generateWeek(p,plan){const s=await session(),recipes=(await allRecipes()).filter(r=>recipeAllowed(r,p));if(!recipes.length)throw new Error('No recipes match your current diet/exclusions.');const mealsPerDay=Number(p.meals_per_day||3),target={calories:Number(p.calorie_target||1800)/mealsPerDay,protein:Number(p.protein_target_g||150)/mealsPerDay,carbs:Number(p.carb_limit_g||150)/mealsPerDay};const ranked=[...recipes].sort((a,b)=>fitScore(a,target)-fitScore(b,target));const n=Number(plan.meals_to_cover||12),chosen=[],pool=ranked.slice(0,Math.min(ranked.length,Math.max(6,Math.ceil(n*.75))));const mode=plan.meal_prep_mode||'some';for(let i=0;i<n;i++){let idx;if(mode==='none') idx=i%pool.length;else if(mode==='batch') idx=Math.floor(i/3)%Math.min(pool.length,Math.max(1,Math.ceil(n/3)));else idx=Math.floor(i/2)%Math.min(pool.length,Math.max(1,Math.ceil(n/2)));chosen.push(pool[idx])}await db.from('weekly_meals').delete().eq('user_id',s.user.id).eq('week_start',plan.week_start);const rows=chosen.map((r,i)=>({user_id:s.user.id,week_start:plan.week_start,slot_number:i+1,recipe_id:r.id,portion:1}));await db.from('weekly_meals').insert(rows);await db.from('weekly_plans').upsert({...plan,user_id:s.user.id,shopping_defined:true,updated_at:new Date().toISOString()},{onConflict:'user_id,week_start'});const meals=await weeklyMeals(plan.week_start);await rebuildGroceries(plan.week_start,meals);return meals}
function recipeCard(w,i,swap=true){const r=w.recipes||w,m=recipeMacros(r),portion=Number(w.portion||1);return `<div class="recipeCard"><div class="recipeEmoji">${r.image_emoji||'🍽️'}</div><div class="recipeBody"><div class="recipeTop"><div><b>${r.name}</b><span>${r.prep_minutes+r.cook_minutes} min</span></div><span class="fitBadge">${macroLine(m,portion)}</span></div><p>${r.description||''}</p><div class="recipeActions">${swap?`<button class="small secondary" data-swap="${i}">Swap</button>`:''}<button class="small secondary" data-recipe="${r.id}">Recipe</button></div></div></div>`}
async function swapPicker(p,ws,meal,index){const all=(await allRecipes()).filter(r=>recipeAllowed(r,p)&&r.id!==meal.recipe_id),base=recipeMacros(meal.recipes);all.sort((a,b)=>Math.abs(recipeMacros(a).calories-base.calories)+2*Math.abs(recipeMacros(a).protein-base.protein)-(Math.abs(recipeMacros(b).calories-base.calories)+2*Math.abs(recipeMacros(b).protein-base.protein)));const options=all.slice(0,8);const content=`<div class="hero"><h1>Swap meal</h1><p>Alternatives are ranked for similar calories and protein. Grocery quantities update automatically.</p></div><div class="card"><div class="swapFrom"><span>Replacing</span><b>${meal.recipes.name}</b><span>${macroLine(base)}</span></div></div>${options.map((r,i)=>recipeCard(r,i,false).replace('data-recipe=',`data-choose="${r.id}" data-recipe=`)).join('')}<button id="cancelSwap" class="secondary">Cancel</button>`;shell(content,p.sex,'Shop');cancelSwap.onclick=()=>shopView(p);document.querySelectorAll('[data-choose]').forEach(b=>b.onclick=async()=>{const s=await session();await db.from('weekly_meals').update({recipe_id:Number(b.dataset.choose)}).eq('user_id',s.user.id).eq('week_start',ws).eq('slot_number',meal.slot_number);const meals=await weeklyMeals(ws);await rebuildGroceries(ws,meals);shopView(p)})}

function practicalAmount(name,g){g=Number(g);const oz=(g/28.3495).toFixed(1);let approx='';const n=(name||'').toLowerCase();if(n.includes('chicken thigh'))approx=` • about ${Math.max(1,Math.round(g/150))} medium boneless thighs`;else if(n.includes('chicken breast'))approx=` • about ${Math.max(1,Math.round(g/180))} medium breasts`;else if(n.includes('egg'))approx=` • about ${Math.max(1,Math.round(g/50))} large eggs`;else if(['broccoli','cauliflower','spinach','romaine lettuce','white cabbage'].some(x=>n.includes(x)))approx=` • about ${(g/90).toFixed(1)} cups`;else if(n.includes('cucumber'))approx=` • about ${(g/120).toFixed(1)} cups chopped`;else if(n.includes('cheese')||n.includes('feta')||n.includes('gouda'))approx=` • about ${(g/113).toFixed(2)} cup`;else if(n.includes('olive oil'))approx=` • about ${(g/4.5).toFixed(1)} tsp`;return `${Math.round(g)} g / ${oz} oz${approx}`}

async function showRecipe(p,id,back='Eat'){const rs=await allRecipes(),r=rs.find(x=>x.id===Number(id));if(!r)return;const m=recipeMacros(r);shell(`<div class="hero recipeHero"><div class="bigEmoji">${r.image_emoji||'🍽️'}</div><h1>${r.name}</h1><p>${r.description||''}</p><div class="macroPills"><span>${Math.round(m.calories)} kcal</span><span>${Math.round(m.protein)}g protein</span><span>${Math.round(m.carbs)}g carbs</span><span>${Math.round(m.fat)}g fat</span></div></div><div class="card"><h2>Ingredients</h2>${r.recipe_ingredients.map(i=>`<div class="ingredient"><b>${i.foods.name}</b><span>${practicalAmount(i.foods.name,i.quantity_g)}</span></div>`).join('')}</div><div class="card"><div class="cardhead"><h2>Quick mode</h2><span>${r.prep_minutes+r.cook_minutes} min</span></div><p>${r.quick_instructions}</p></div><div class="card beginnerNote"><b>Beginner-friendly cook mode</b><span>Read the whole recipe once before starting. Gather and measure everything first. Use a food thermometer for meat and poultry.</span></div><div class="card"><h2>Cook mode</h2><div class="steps">${String(r.detailed_instructions||'').split('\n').map(x=>`<p>${x}</p>`).join('')}</div></div><button id="recipeBack" class="secondary">Back</button>`,p.sex,back);recipeBack.onclick=()=>back==='Shop'?shopView(p):eatView(p)}

async function shopView(p){const s=await session(),ws=weekStart();let {data:plan}=await db.from('weekly_plans').select('*').eq('week_start',ws).maybeSingle();if(!plan)plan={user_id:s.user.id,week_start:ws,meals_to_cover:12,budget:p.grocery_budget,currency:p.currency||'USD',shopping_defined:false};const meals=await weeklyMeals(ws),{data:groceries}=await db.from('grocery_items').select('*,foods(*),stores(*)').eq('week_start',ws).order('food_id'),{data:stores}=await db.from('stores').select('*').order('name');const locked=!!plan.locked_at;const mealHtml=meals.length?meals.map((w,i)=>recipeCard(w,i,!locked)).join(''):'<div class="emptyState"><b>No week generated yet.</b><span>Tell FatBoySchlim how many meals to cover, then generate your week.</span></div>';shell(`<div class="hero colorful"><span class="eyebrow">${locked?'THIS WEEK • LOCKED':'WEEKLY MISSION'}</span><h1>Shop</h1><p>${locked?'Your meals and grocery list are locked in. Check off purchases and live the week.':'Generate more structure, keep the choice. Swap anything you don\'t feel like eating.'}</p></div>${locked?`<div class="card lockCard"><h2>Week locked in 🔒</h2><p>Your plan is protected from accidental regeneration. You can still check off groceries and choose meals in Eat.</p><div class="row"><button id="editWeek" class="secondary">Edit week</button><button id="nextWeek">Plan next week</button></div></div>`:`<div class="card planner"><div><span class="label">Meals to cover</span><div class="stepper"><button id="minusMeal" class="tiny secondary">−</button><input id="coverMeals" type="number" min="1" max="35" value="${plan.meals_to_cover||12}"><button id="plusMeal" class="tiny secondary">+</button></div></div><label>Weekly budget (${plan.currency||p.currency||'USD'})<input id="shopBudget" type="number" value="${plan.budget??p.grocery_budget??''}"></label><label>Meal prep<select id="mealPrep"><option value="none" ${plan.meal_prep_mode==='none'?'selected':''}>No meal prep</option><option value="some" ${(!plan.meal_prep_mode||plan.meal_prep_mode==='some')?'selected':''}>Some meal prep</option><option value="batch" ${plan.meal_prep_mode==='batch'?'selected':''}>Single-day meal prep</option></select></label><button id="generatePlan">${meals.length?'Regenerate week':'Generate my week'}</button><p id="shopMsg"></p>${meals.length?'<button id="lockWeek" class="lockButton">🔒 Lock in this week</button>':''}</div>`}<div class="sectionTitle"><div><span class="eyebrow">YOUR PICKS</span><h2>${meals.length} / ${plan.meals_to_cover||12} meals</h2></div>${meals.length?'<span class="successDot">● Ready to swap</span>':''}</div>${mealHtml}<div class="card"><div class="cardhead"><div><span class="eyebrow">AUTO-BUILT</span><h2>Grocery list</h2></div><span>${groceries?.length||0} items</span></div>${groceries?.length?groceries.map(g=>`<label class="grocery"><input type="checkbox" data-buy="${g.id}" ${g.purchased?'checked':''}><span><b>${g.foods?.name||'Food'}</b><small>${Math.ceil(Number(g.quantity_g))} g needed</small></span><select data-store="${g.id}"><option value="">Store</option>${(stores||[]).map(st=>`<option value="${st.id}" ${g.store_id===st.id?'selected':''}>${st.name}</option>`).join('')}</select></label>`).join(''):'<p class="muted">Generate a week and the grocery list will appear here automatically.</p>'}</div>`,p.sex,'Shop');if(!locked){minusMeal.onclick=()=>coverMeals.value=Math.max(1,Number(coverMeals.value)-1);plusMeal.onclick=()=>coverMeals.value=Math.min(35,Number(coverMeals.value)+1);generatePlan.onclick=async()=>{shopMsg.textContent='Building your week…';const row={...plan,user_id:s.user.id,week_start:ws,meals_to_cover:num('coverMeals')||12,budget:num('shopBudget'),currency:p.currency||'USD',meal_prep_mode:val('mealPrep')||'some'};await db.from('weekly_plans').upsert(row,{onConflict:'user_id,week_start'});try{await generateWeek(p,row);shopView(p)}catch(e){shopMsg.textContent=e.message}};if(document.querySelector('#lockWeek'))lockWeek.onclick=async()=>{await db.from('weekly_plans').update({locked_at:new Date().toISOString(),plan_status:'locked',shopping_defined:true,updated_at:new Date().toISOString()}).eq('user_id',s.user.id).eq('week_start',ws);shopView(p)};}else{editWeek.onclick=async()=>{if(confirm('Unlock this week? Changes to meals can change your grocery requirements.')){await db.from('weekly_plans').update({locked_at:null,plan_status:'planning',updated_at:new Date().toISOString()}).eq('user_id',s.user.id).eq('week_start',ws);shopView(p)}};nextWeek.onclick=()=>alert('Next-week planning is coming next; this week stays safely locked.');}document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>swapPicker(p,ws,meals[Number(b.dataset.swap)],Number(b.dataset.swap)));document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>showRecipe(p,b.dataset.recipe,'Shop'));document.querySelectorAll('[data-buy]').forEach(c=>c.onchange=()=>db.from('grocery_items').update({purchased:c.checked,updated_at:new Date().toISOString()}).eq('id',c.dataset.buy));document.querySelectorAll('[data-store]').forEach(x=>x.onchange=()=>db.from('grocery_items').update({store_id:x.value?Number(x.value):null,updated_at:new Date().toISOString()}).eq('id',x.dataset.store))}

async function eatView(p,date=today()){const target=await ensureDailyTarget(p,date),{data:logs}=await db.from('food_logs').select('*').eq('logged_on',date).order('created_at'),ws=weekStart(),{data:plan}=await db.from('weekly_plans').select('*').eq('week_start',ws).maybeSingle(),meals=plan?.shopping_defined?await weeklyMeals(ws):[],sum=k=>(logs||[]).reduce((a,x)=>a+Number(x[k]||0),0),used={calories:sum('calories'),protein:sum('protein_g'),carbs:sum('carbs_g'),fat:sum('fat_g')},remaining={calories:(target?.calories||0)-used.calories,protein:(target?.protein_g||0)-used.protein,carbs:(target?.carbs_g||0)-used.carbs,fat:(target?.fat_g||0)-used.fat};let ranked=[...meals].sort((a,b)=>Math.abs(recipeMacros(a.recipes).calories-Math.max(0,remaining.calories)/Math.max(1,(p.meals_per_day||3)-1))-Math.abs(recipeMacros(b.recipes).calories-Math.max(0,remaining.calories)/Math.max(1,(p.meals_per_day||3)-1)));shell(`<div class="hero colorful"><span class="eyebrow">TODAY</span><h1>Eat</h1><p>${Math.max(0,Math.round(remaining.calories))} calories and ${Math.max(0,Math.round(remaining.protein))}g protein remaining.</p></div><div class="card macroCard">${macroStat('Calories',used.calories,target?.calories,'kcal')}${macroStat('Protein',used.protein,target?.protein_g,'g')}${macroStat('Carbs',used.carbs,target?.carbs_g,'g')}${macroStat('Fat',used.fat,target?.fat_g,'g')}</div><div class="datebar card"><button id="prev" class="tiny secondary">‹</button><input id="eatDate" type="date" value="${date}"><button id="next" class="tiny secondary">›</button></div><div class="sectionTitle"><div><span class="eyebrow">FROM YOUR WEEK</span><h2>Pick what sounds good</h2></div></div>${ranked.length?ranked.slice(0,8).map((w,i)=>{const m=recipeMacros(w.recipes),suggest=Math.max(.5,Math.min(1.5,remaining.calories>0?remaining.calories/m.calories:1));return `<div class="recipeCard"><div class="recipeEmoji">${w.recipes.image_emoji}</div><div class="recipeBody"><b>${w.recipes.name}</b><span>${macroLine(m)}</span><p>${w.recipes.description}</p><div class="portionRow"><label>Portion <select data-portion="${i}"><option value="0.5">½</option><option value="0.75">¾</option><option value="1" selected>1</option><option value="1.25">1¼</option><option value="1.5">1½</option></select></label><button data-eatmeal="${i}">I ate this</button><button class="small secondary" data-recipe="${w.recipes.id}">Recipe</button></div></div></div>`}).join(''):`<div class="emptyState"><b>Meals unlock after you build this week's shopping plan.</b><span>Go to Shop → choose how many meals you want → Generate my week.</span><button id="goShop">Build my week</button></div>`}<div class="card"><div class="cardhead"><h2>What you ate</h2><button id="manualToggle" class="small secondary">+ Log something else</button></div><div id="dayLogs">${renderLogs(logs)}</div><div id="manualBox" class="hidden"><p class="muted">Manual logging is here for restaurants, snacks and anything outside your FatBoySchlim recipes.</p><div class="formgrid"><label>Name<input id="foodName"></label><label>Meal<select id="slot"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option><option>Other</option></select></label><label>Calories<input id="logCal" type="number"></label><label>Protein g<input id="logPro" type="number"></label><label>Carbs g<input id="logCar" type="number"></label><label>Fat g<input id="logFat" type="number"></label></div><button id="addFood">Add</button></div></div>`,p.sex,'Eat');const shift=n=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);eatView(p,d.toISOString().slice(0,10))};prev.onclick=()=>shift(-1);next.onclick=()=>shift(1);eatDate.onchange=()=>eatView(p,eatDate.value);if(document.querySelector('#goShop'))goShop.onclick=()=>shopView(p);document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>showRecipe(p,b.dataset.recipe,'Eat'));document.querySelectorAll('[data-eatmeal]').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.eatmeal),w=ranked[i],r=w.recipes,m=recipeMacros(r),portion=Number(document.querySelector(`[data-portion="${i}"]`).value),s=await session();await db.from('food_logs').insert({user_id:s.user.id,logged_on:date,meal_slot:'Other',item_name:r.name,servings:portion,calories:m.calories*portion,protein_g:m.protein*portion,carbs_g:m.carbs*portion,fat_g:m.fat*portion});eatView(p,date)});manualToggle.onclick=()=>manualBox.classList.toggle('hidden');addFood.onclick=async()=>{const s=await session();await db.from('food_logs').insert({user_id:s.user.id,logged_on:date,meal_slot:slot.value,item_name:foodName.value||'Manual item',calories:num('logCal')||0,protein_g:num('logPro')||0,carbs_g:num('logCar')||0,fat_g:num('logFat')||0});eatView(p,date)}}

// v0.6.1 — clearer Shop → Eat workflow + store price learning
function money(n,c='USD'){if(n==null||!Number.isFinite(Number(n)))return '—';try{return new Intl.NumberFormat(undefined,{style:'currency',currency:c||'USD'}).format(Number(n))}catch{return `${c||''} ${Number(n).toFixed(2)}`} }
async function latestStorePrices(storeId){if(!storeId)return{};const s=await session();const {data}=await db.from('food_prices').select('*').eq('user_id',s.user.id).eq('store_id',storeId).order('purchased_on',{ascending:false}).order('created_at',{ascending:false});const out={};(data||[]).forEach(x=>{if(!out[x.food_id])out[x.food_id]=x});return out}
function estimateGrocery(g,price){if(!price||!Number(price.package_quantity)||!Number(price.price))return null;let q=Number(g.quantity_g||0),pq=Number(price.package_quantity);if(String(price.package_unit||'g').toLowerCase()==='kg')pq*=1000;else if(['oz','ounce','ounces'].includes(String(price.package_unit||'').toLowerCase()))pq*=28.3495;else if(['lb','lbs','pound','pounds'].includes(String(price.package_unit||'').toLowerCase()))pq*=453.592;return Math.ceil(q/pq)*Number(price.price)}
async function saveObservedPrice(g,storeId,actual){if(!storeId||!actual||actual<=0)return;const s=await session();await db.from('food_prices').insert({user_id:s.user.id,food_id:g.food_id,store_id:storeId,price:actual,package_quantity:Number(g.quantity_g||0),package_unit:'g',purchased_on:today()})}

async function shopView(p){
 const s=await session(),ws=weekStart();let {data:plan}=await db.from('weekly_plans').select('*').eq('week_start',ws).maybeSingle();
 if(!plan)plan={user_id:s.user.id,week_start:ws,meals_to_cover:12,budget:p.grocery_budget,currency:p.currency||'USD',shopping_defined:false};
 const meals=await weeklyMeals(ws),{data:groceries}=await db.from('grocery_items').select('*,foods(*),stores(*)').eq('week_start',ws).order('food_id'),{data:stores}=await db.from('stores').select('*').order('name');
 const locked=!!plan.locked_at,storeId=Number(plan.preferred_store_id||0)||null,prices=await latestStorePrices(storeId),currency=(stores||[]).find(x=>x.id===storeId)?.currency||plan.currency||p.currency||'USD';
 const estimates=(groceries||[]).map(g=>estimateGrocery(g,prices[g.food_id])),known=estimates.filter(x=>x!=null),estimatedTotal=known.length?known.reduce((a,b)=>a+b,0):null,budget=Number(plan.budget??p.grocery_budget??0),remaining=estimatedTotal==null?null:budget-estimatedTotal;
 const groceryHtml=(groceries||[]).length?(groceries||[]).map((g,i)=>{const est=estimates[i],pr=prices[g.food_id];return `<div class="grocery grocery061"><input type="checkbox" data-buy="${g.id}" ${g.purchased?'checked':''}><span class="groceryMain"><b>${g.foods?.name||'Food'}</b><small>${Math.ceil(Number(g.quantity_g))} g needed${pr?` • based on ${money(pr.price,currency)} / ${Number(pr.package_quantity)} ${pr.package_unit||'g'}`:''}</small></span><b class="groceryPrice">${est==null?'No price yet':money(est,currency)}</b><input class="actualPrice" data-actual="${g.id}" type="number" min="0" step=".01" placeholder="Actual" value="${g.actual_price??''}"></div>`}).join(''):'<p class="muted">Generate a week and your grocery list will appear here automatically.</p>';
 const mealHtml=meals.length?meals.map((w,i)=>recipeCard(w,i,!locked)).join(''):'<div class="emptyState"><b>No meals selected yet.</b><span>Set your week below and FatBoySchlim will build a meal set and grocery list together.</span></div>';
 shell(`<div class="hero colorful"><span class="eyebrow">${locked?'SHOPPING MODE • WEEK LOCKED':'PLAN + BUY'}</span><h1>Shop</h1><p>${locked?'Your list is the main event now. Check items off and record what you actually paid.':'Build the week here. Meals and groceries are one planning workflow.'}</p></div>
 ${locked?`<div class="card priceHero"><div><span class="eyebrow">ESTIMATED CART</span><div class="bigMoney">${estimatedTotal==null?'Need prices':money(estimatedTotal,currency)}</div><span>${known.length}/${(groceries||[]).length} items priced${budget?` • ${remaining==null?'':money(Math.abs(remaining),currency)+(remaining>=0?' under budget':' over budget')}`:''}</span></div><label>Shopping store<select id="mainStore"><option value="">Choose store</option>${(stores||[]).map(st=>`<option value="${st.id}" ${storeId===st.id?'selected':''}>${st.name}</option>`).join('')}</select></label></div><div class="card groceryCard"><div class="cardhead"><div><span class="eyebrow">YOUR LIST</span><h2>Grocery list</h2></div><span>${(groceries||[]).filter(g=>g.purchased).length}/${(groceries||[]).length} bought</span></div>${groceryHtml}<p class="hint">Enter the actual checkout price for an item. FatBoySchlim remembers it for this store and uses it to improve future estimates.</p></div><div class="card lockCard"><h2>Week locked 🔒</h2><p>Meal planning is frozen so your grocery quantities don't change by accident.</p><button id="editWeek" class="secondary">Edit week</button></div><details class="card"><summary><b>See this week's ${meals.length} meals</b></summary>${mealHtml}</details>`:
 `<div class="card planner"><div class="formgrid"><label>Meals to cover<input id="coverMeals" type="number" min="1" max="35" value="${plan.meals_to_cover||12}"></label><label>Budget (${currency})<input id="shopBudget" type="number" value="${plan.budget??p.grocery_budget??''}"></label><label>Meal prep<select id="mealPrep"><option value="none" ${plan.meal_prep_mode==='none'?'selected':''}>No meal prep</option><option value="some" ${(!plan.meal_prep_mode||plan.meal_prep_mode==='some')?'selected':''}>Some meal prep</option><option value="batch" ${plan.meal_prep_mode==='batch'?'selected':''}>Single-day meal prep</option></select></label><label>Primary store<select id="mainStore"><option value="">Choose store</option>${(stores||[]).map(st=>`<option value="${st.id}" ${storeId===st.id?'selected':''}>${st.name}</option>`).join('')}</select></label></div><button id="generatePlan">${meals.length?'Regenerate meals':'Generate meals'}</button><p id="shopMsg"></p></div><div class="sectionTitle"><div><span class="eyebrow">STEP 2 • REVIEW</span><h2>${meals.length?`${meals.length} meals selected`:'Choose your meals'}</h2></div></div>${mealHtml}${meals.length?`<div class="card priceHero"><div><span class="eyebrow">PREVIEW CART</span><div class="bigMoney">${estimatedTotal==null?'Choose/teach a store':money(estimatedTotal,currency)}</div><span>${known.length}/${(groceries||[]).length} items have price history</span></div></div><div class="card groceryCard"><div class="cardhead"><h2>Grocery preview</h2><span>${(groceries||[]).length} items</span></div>${groceryHtml}</div><button id="lockWeek" class="lockButton">🔒 Lock meals + shopping list</button>`:''}`}
 `,p.sex,'Shop');
 if(document.querySelector('#mainStore'))mainStore.onchange=async()=>{await db.from('weekly_plans').upsert({...plan,user_id:s.user.id,week_start:ws,preferred_store_id:mainStore.value?Number(mainStore.value):null,updated_at:new Date().toISOString()},{onConflict:'user_id,week_start'});shopView(p)};
 if(!locked){generatePlan.onclick=async()=>{shopMsg.textContent='Building your week…';const row={...plan,user_id:s.user.id,week_start:ws,meals_to_cover:num('coverMeals')||12,budget:num('shopBudget'),currency:p.currency||'USD',meal_prep_mode:val('mealPrep')||'some',preferred_store_id:val('mainStore')?Number(val('mainStore')):null};await db.from('weekly_plans').upsert(row,{onConflict:'user_id,week_start'});try{await generateWeek(p,row);shopView(p)}catch(e){shopMsg.textContent=e.message}};if(document.querySelector('#lockWeek'))lockWeek.onclick=async()=>{await db.from('weekly_plans').update({locked_at:new Date().toISOString(),plan_status:'locked',shopping_defined:true,updated_at:new Date().toISOString()}).eq('user_id',s.user.id).eq('week_start',ws);shopView(p)}}else editWeek.onclick=async()=>{if(confirm('Unlock this week? Changing meals can change your grocery list.')){await db.from('weekly_plans').update({locked_at:null,plan_status:'planning',updated_at:new Date().toISOString()}).eq('user_id',s.user.id).eq('week_start',ws);shopView(p)}};
 document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>swapPicker(p,ws,meals[Number(b.dataset.swap)],Number(b.dataset.swap)));document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>showRecipe(p,b.dataset.recipe,'Shop'));
 document.querySelectorAll('[data-buy]').forEach(c=>c.onchange=()=>db.from('grocery_items').update({purchased:c.checked,updated_at:new Date().toISOString()}).eq('id',c.dataset.buy));
 document.querySelectorAll('[data-actual]').forEach(x=>x.onchange=async()=>{const g=(groceries||[]).find(z=>String(z.id)===String(x.dataset.actual)),actual=Number(x.value||0);await db.from('grocery_items').update({actual_price:actual||null,updated_at:new Date().toISOString()}).eq('id',x.dataset.actual);if(g&&actual>0&&storeId)await saveObservedPrice(g,storeId,actual)});
}

async function eatView(p,date=today()){
 const target=await ensureDailyTarget(p,date),{data:logs}=await db.from('food_logs').select('*').eq('logged_on',date).order('created_at'),ws=weekStart(),{data:plan}=await db.from('weekly_plans').select('*').eq('week_start',ws).maybeSingle(),meals=plan?.locked_at?await weeklyMeals(ws):[],sum=k=>(logs||[]).reduce((a,x)=>a+Number(x[k]||0),0),used={calories:sum('calories'),protein:sum('protein_g'),carbs:sum('carbs_g'),fat:sum('fat_g')},remaining={calories:(target?.calories||0)-used.calories,protein:(target?.protein_g||0)-used.protein,carbs:(target?.carbs_g||0)-used.carbs,fat:(target?.fat_g||0)-used.fat};
 const ranked=[...meals].sort((a,b)=>Math.abs(recipeMacros(a.recipes).calories-Math.max(0,remaining.calories)/Math.max(1,(p.meals_per_day||3)-1))-Math.abs(recipeMacros(b.recipes).calories-Math.max(0,remaining.calories)/Math.max(1,(p.meals_per_day||3)-1)));
 shell(`<div class="hero colorful"><span class="eyebrow">EAT • EXECUTE</span><h1>What's good right now?</h1><p>${Math.max(0,Math.round(remaining.calories))} calories • ${Math.max(0,Math.round(remaining.protein))}g protein remaining today.</p></div><div class="card macroCard">${macroStat('Calories',used.calories,target?.calories,'kcal')}${macroStat('Protein',used.protein,target?.protein_g,'g')}${macroStat('Carbs',used.carbs,target?.carbs_g,'g')}${macroStat('Fat',used.fat,target?.fat_g,'g')}</div><div class="datebar card"><button id="prev" class="tiny secondary">‹</button><input id="eatDate" type="date" value="${date}"><button id="next" class="tiny secondary">›</button></div><div class="sectionTitle"><div><span class="eyebrow">FROM YOUR LOCKED WEEK</span><h2>${ranked.length?`${ranked.length} planned meals`:'No active meal pool'}</h2></div></div>${ranked.length?ranked.map((w,i)=>{const m=recipeMacros(w.recipes);return `<div class="recipeCard"><div class="recipeEmoji">${w.recipes.image_emoji}</div><div class="recipeBody"><b>${w.recipes.name}</b><span>${macroLine(m)}</span><p>${w.recipes.description}</p><div class="portionRow"><label>Portion <select data-portion="${i}"><option value="0.5">½</option><option value="0.75">¾</option><option value="1" selected>1</option><option value="1.25">1¼</option><option value="1.5">1½</option></select></label><button data-eatmeal="${i}">I ate this</button><button class="small secondary" data-recipe="${w.recipes.id}">Cook / recipe</button></div></div></div>`}).join(''):`<div class="emptyState"><b>Lock a week before Eat fills up.</b><span>Meal planning and grocery work now live entirely in Shop.</span><button id="goShop">Go to Shop</button></div>`}<div class="card"><div class="cardhead"><h2>Today's log</h2><button id="manualToggle" class="small secondary">+ Log something else</button></div><div id="dayLogs">${renderLogs(logs)}</div><div id="manualBox" class="hidden"><div class="formgrid"><label>Name<input id="foodName"></label><label>Meal<select id="slot"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option><option>Other</option></select></label><label>Calories<input id="logCal" type="number"></label><label>Protein g<input id="logPro" type="number"></label><label>Carbs g<input id="logCar" type="number"></label><label>Fat g<input id="logFat" type="number"></label></div><button id="addFood">Add</button></div></div>`,p.sex,'Eat');
 const shift=n=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);eatView(p,d.toISOString().slice(0,10))};prev.onclick=()=>shift(-1);next.onclick=()=>shift(1);eatDate.onchange=()=>eatView(p,eatDate.value);if(document.querySelector('#goShop'))goShop.onclick=()=>shopView(p);document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>showRecipe(p,b.dataset.recipe,'Eat'));document.querySelectorAll('[data-eatmeal]').forEach(b=>b.onclick=async()=>{const i=Number(b.dataset.eatmeal),w=ranked[i],r=w.recipes,m=recipeMacros(r),portion=Number(document.querySelector(`[data-portion="${i}"]`).value),s=await session();await db.from('food_logs').insert({user_id:s.user.id,logged_on:date,meal_slot:'Other',item_name:r.name,servings:portion,calories:m.calories*portion,protein_g:m.protein*portion,carbs_g:m.carbs*portion,fat_g:m.fat*portion});eatView(p,date)});manualToggle.onclick=()=>manualBox.classList.toggle('hidden');addFood.onclick=async()=>{const s=await session();await db.from('food_logs').insert({user_id:s.user.id,logged_on:date,meal_slot:slot.value,item_name:foodName.value||'Manual item',calories:num('logCal')||0,protein_g:num('logPro')||0,carbs_g:num('logCar')||0,fat_g:num('logFat')||0});eatView(p,date)};
}

// ===== v0.7 cookbook + swap UX overrides =====
function recipeCard(w,i,swap=true){const r=w.recipes||w,m=recipeMacros(r),portion=Number(w.portion||1),types=r.meal_types||[],tags=(r.tags||[]).slice(0,3);return `<div class="recipeCard"><img class="recipePhoto" src="${r.photo_url||''}" alt="${r.name}" onerror="this.style.display='none'"><div class="recipeBody"><div class="recipeTop"><div><b>${r.name}</b><span>${r.difficulty||'Easy'} • ${Number(r.prep_minutes||0)+Number(r.cook_minutes||0)} min</span></div><span class="fitBadge">${macroLine(m,portion)}</span></div><div class="mealTypes">${types.map(x=>`<span class="typeChip">${x.toUpperCase()}</span>`).join('')}${tags.map(x=>`<span class="dietChip">${String(x).replaceAll('-',' ').toUpperCase()}</span>`).join('')}</div><p>${r.description||''}</p><div class="recipeActions">${swap?`<button class="replaceButton" data-swap="${i}">Replace meal</button>`:''}<button class="small secondary" data-recipe="${r.id}">Cook / recipe</button></div></div></div>`}

async function swapPicker(p,ws,meal,index){const current=await weeklyMeals(ws),used=new Set(current.map(x=>Number(x.recipe_id))),all=(await allRecipes()).filter(r=>recipeAllowed(r,p)&&!used.has(Number(r.id))),base=recipeMacros(meal.recipes),baseTypes=meal.recipes.meal_types||[];all.sort((a,b)=>{const score=r=>Math.abs(recipeMacros(r).calories-base.calories)+2*Math.abs(recipeMacros(r).protein-base.protein)+25*(baseTypes.some(t=>(r.meal_types||[]).includes(t))?0:1);return score(a)-score(b)});const options=all.slice(0,5);shell(`<div class="hero colorful"><span class="eyebrow">REPLACE MEAL</span><h1>Replacing ${meal.recipes.name}</h1><p>These are the closest unused matches for this week. Choosing one immediately updates your groceries and estimated cart.</p></div><div class="card"><b>Current meal</b><p>${macroLine(base)} • ${(meal.recipes.meal_types||[]).join(' / ')}</p></div><div class="sectionTitle"><div><span class="eyebrow">BEST MATCHES</span><h2>Pick a replacement</h2></div></div>${options.length?options.map((r,i)=>{const m=recipeMacros(r);return `<div class="recipeCard swapChoice"><img class="recipePhoto" src="${r.photo_url||''}" alt="${r.name}"><div class="recipeBody"><b>${r.name}</b><div class="mealTypes">${(r.meal_types||[]).map(x=>`<span class="typeChip">${x.toUpperCase()}</span>`).join('')}</div><span>${macroLine(m)}</span><p>${r.description||''}</p><button class="replaceButton" data-choose="${r.id}">USE THIS MEAL</button></div></div>`}).join(''):`<div class="emptyState"><b>No unused matches available.</b><span>Regenerate the week or expand your diet filters.</span></div>`}<button id="cancelSwap" class="secondary">Cancel replacement</button>`,p.sex,'Shop');cancelSwap.onclick=()=>shopView(p);document.querySelectorAll('[data-choose]').forEach(b=>b.onclick=async()=>{const s=await session();b.disabled=true;b.textContent='Replacing…';await db.from('weekly_meals').update({recipe_id:Number(b.dataset.choose)}).eq('user_id',s.user.id).eq('week_start',ws).eq('slot_number',meal.slot_number);const meals=await weeklyMeals(ws);await rebuildGroceries(ws,meals);shopView(p)})}

async function generateWeek(p,plan){const s=await session(),recipes=(await allRecipes()).filter(r=>recipeAllowed(r,p));if(!recipes.length)throw new Error('No recipes match your current diet/exclusions.');const mealsPerDay=Number(p.meals_per_day||3),target={calories:Number(p.calorie_target||1800)/mealsPerDay,protein:Number(p.protein_target_g||150)/mealsPerDay,carbs:Number(p.carb_limit_g||150)/mealsPerDay},n=Number(plan.meals_to_cover||12),mode=plan.meal_prep_mode||'some',pattern=['Dinner','Lunch','Dinner','Breakfast','Lunch','Dinner','Breakfast','Lunch','Dinner','Snack'],chosen=[],counts={};function pick(type){let pool=recipes.filter(r=>(r.meal_types||[]).includes(type));if(!pool.length)pool=recipes;pool=[...pool].sort((a,b)=>fitScore(a,target)-fitScore(b,target));if(mode==='none'){const fresh=pool.find(r=>!counts[r.id]);if(fresh)return fresh}if(mode==='some'){const repeat=pool.find(r=>(counts[r.id]||0)===1);if(repeat&&chosen.length%3===1)return repeat;return pool.find(r=>(counts[r.id]||0)===0)||pool[0]}if(mode==='batch'){const repeat=pool.find(r=>(counts[r.id]||0)>0&&(counts[r.id]||0)<3);return repeat||pool.find(r=>!counts[r.id])||pool[0]}return pool[0]}
for(let i=0;i<n;i++){const r=pick(pattern[i%pattern.length]);chosen.push(r);counts[r.id]=(counts[r.id]||0)+1}await db.from('weekly_meals').delete().eq('user_id',s.user.id).eq('week_start',plan.week_start);await db.from('weekly_meals').insert(chosen.map((r,i)=>({user_id:s.user.id,week_start:plan.week_start,slot_number:i+1,recipe_id:r.id,portion:1})));await db.from('weekly_plans').upsert({...plan,user_id:s.user.id,shopping_defined:true,updated_at:new Date().toISOString()},{onConflict:'user_id,week_start'});const meals=await weeklyMeals(plan.week_start);await rebuildGroceries(plan.week_start,meals);return meals}

function methodButtons(methods){const names=Object.keys(methods||{});return names.map((x,i)=>`<button class="small secondary ${i===0?'active':''}" data-method="${x}">${x}</button>`).join('')}
function renderMethod(r,name){const m=(r.cooking_methods||{})[name];if(!m)return '<p>No method available.</p>';return `<div class="card"><h2>${name} Cook Mode</h2><p><b>Equipment:</b> ${m.equipment||r.equipment||'Basic kitchen equipment'}</p><div class="steps">${(m.steps||[]).map((x,i)=>`<div class="cookStep"><b>STEP ${i+1} OF ${m.steps.length}</b>${x}</div>`).join('')}</div></div>`}
async function showRecipe(p,id,back='Eat'){const rs=await allRecipes(),r=rs.find(x=>x.id===Number(id));if(!r)return;const m=recipeMacros(r),methods=r.cooking_methods||{},first=Object.keys(methods)[0];shell(`<div class="hero recipeHero"><img class="recipeHeroPhoto" src="${r.photo_url||''}" alt="${r.name}"><div class="mealTypes">${(r.meal_types||[]).map(x=>`<span class="typeChip">${x.toUpperCase()}</span>`).join('')}${(r.tags||[]).slice(0,4).map(x=>`<span class="dietChip">${String(x).replaceAll('-',' ').toUpperCase()}</span>`).join('')}</div><h1>${r.name}</h1><p>${r.description||''}</p><div class="macroPills"><span>${Math.round(m.calories)} kcal</span><span>${Math.round(m.protein)}g protein</span><span>${Math.round(m.carbs)}g carbs</span><span>${Math.round(m.fat)}g fat</span></div></div><div class="card"><div class="cardhead"><h2>Portion</h2><span>${r.difficulty||'Easy'} • ${Number(r.prep_minutes||0)+Number(r.cook_minutes||0)} min</span></div><p>${r.portion_description||'1 serving'}</p><label>Servings to make<select id="recipeServings"><option value="1">1 serving</option><option value="2">2 servings</option><option value="3">3 servings</option><option value="4">4 servings</option><option value="6">6 servings</option></select></label></div><div class="card"><h2>Ingredients</h2><div id="scaledIngredients">${r.recipe_ingredients.map(i=>`<div class="ingredient"><b>${i.foods.name}</b><span>${practicalAmount(i.foods.name,i.quantity_g)}</span></div>`).join('')}</div></div><div class="card"><h2>Choose how you're cooking</h2><p class="muted">Only methods that make sense for this recipe are shown.</p><div class="methodTabs">${methodButtons(methods)}</div></div><div id="cookMethod">${renderMethod(r,first)}</div><div class="card"><h2>Meal prep & leftovers</h2><p><b>Storage:</b> ${r.storage_instructions||''}</p><p><b>Reheating:</b> ${r.reheating_instructions||''}</p><div class="prepControls"><label>Prepared portions<input id="prepCount" type="number" min="1" max="12" value="2"></label><button id="savePrep">Save prepared portions</button></div><p id="prepMsg"></p></div><p class="photoNote">Prototype photography is dynamically sourced food imagery; exact standardized FatBoySchlim recipe photography will replace it as the visual library is produced.</p><button id="recipeBack" class="secondary">Back</button>`,p.sex,back);recipeServings.onchange=()=>{const mult=Number(recipeServings.value);scaledIngredients.innerHTML=r.recipe_ingredients.map(i=>`<div class="ingredient"><b>${i.foods.name}</b><span>${practicalAmount(i.foods.name,Number(i.quantity_g)*mult)}</span></div>`).join('')};document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-method]').forEach(x=>x.classList.remove('active'));b.classList.add('active');cookMethod.innerHTML=renderMethod(r,b.dataset.method)});savePrep.onclick=async()=>{const s=await session(),n=Number(prepCount.value||1);const {error}=await db.from('prepared_meals').insert({user_id:s.user.id,recipe_id:r.id,prepared_on:today(),portions_prepared:n,portions_remaining:n});prepMsg.textContent=error?error.message:`Saved ${n} prepared portion${n===1?'':'s'} ✓`};recipeBack.onclick=()=>back==='Shop'?shopView(p):eatView(p)}

// ===== v0.8 Smart Food Ecosystem overrides =====
function recipeVisual(r,cls='recipePhoto'){
  if(r.photo_url && ['exact','close'].includes(r.image_status)) return `<img class="${cls}" src="${r.photo_url}" alt="${r.image_alt||r.name}" onerror="this.outerHTML='<div class=\'recipePlaceholder\'>🍽️<span>Photo coming soon</span></div>'">`;
  return `<div class="recipePlaceholder ${cls}"><span class="plate">🍽️</span><small>Exact photo coming soon</small></div>`;
}
async function pantryMap(){const {data}=await db.from('pantry_items').select('*');const o={};(data||[]).forEach(x=>o[x.food_id]=Number(x.quantity||0));return o}
async function feedbackMap(){const {data}=await db.from('recipe_feedback').select('*');const o={};(data||[]).forEach(x=>o[x.recipe_id]=x.rating);return o}
async function preparedMeals(){const {data}=await db.from('prepared_meals').select('*,recipes(*,recipe_ingredients(*,foods(*)))').gt('portions_remaining',0).order('prepared_on',{ascending:false});return data||[]}
function pantryCoverage(r,pantry){let need=0,have=0;(r.recipe_ingredients||[]).forEach(i=>{const q=Number(i.quantity_g||0);need+=q;have+=Math.min(q,Number(pantry[i.food_id]||0))});return need?have/need:0}
async function adjustPantry(foodId,delta){const s=await session();const {data}=await db.from('pantry_items').select('*').eq('food_id',foodId).maybeSingle();const q=Math.max(0,Number(data?.quantity||0)+Number(delta||0));await db.from('pantry_items').upsert({user_id:s.user.id,food_id:foodId,quantity:q,unit:'g',updated_at:new Date().toISOString()},{onConflict:'user_id,food_id'})}
async function consumeRecipe(r,servings=1){for(const i of (r.recipe_ingredients||[]))await adjustPantry(i.food_id,-Number(i.quantity_g||0)*servings)}
async function rebuildGroceries(ws,meals){const s=await session(),pantry=await pantryMap(),agg={};meals.forEach(w=>(w.recipes?.recipe_ingredients||[]).forEach(i=>agg[i.food_id]=(agg[i.food_id]||0)+Number(i.quantity_g)*Number(w.portion||1)));await db.from('grocery_items').delete().eq('user_id',s.user.id).eq('week_start',ws);const rows=Object.entries(agg).map(([food_id,total])=>({user_id:s.user.id,week_start:ws,food_id:Number(food_id),quantity_g:Math.max(0,Number(total)-Number(pantry[food_id]||0))})).filter(x=>x.quantity_g>1);if(rows.length)await db.from('grocery_items').insert(rows)}
function recipeCard(w,i,swap=true){const r=w.recipes||w,m=recipeMacros(r),portion=Number(w.portion||1),types=r.meal_types||[],tags=(r.tags||[]).slice(0,3);return `<div class="recipeCard">${recipeVisual(r)}<div class="recipeBody"><div class="recipeTop"><div><b>${r.name}</b><span>${r.difficulty||'Easy'} • ${Number(r.prep_minutes||0)+Number(r.cook_minutes||0)} min</span></div><span class="fitBadge">${macroLine(m,portion)}</span></div><div class="mealTypes">${types.map(x=>`<span class="typeChip">${x.toUpperCase()}</span>`).join('')}${tags.map(x=>`<span class="dietChip">${String(x).replaceAll('-',' ').toUpperCase()}</span>`).join('')}</div><p>${r.description||''}</p><div class="recipeActions">${swap?`<button class="replaceButton" data-swap="${i}">Replace meal</button>`:''}<button class="small secondary" data-recipe="${r.id}">Cook / recipe</button></div></div></div>`}
async function generateWeek(p,plan){const s=await session(),pantry=await pantryMap(),fb=await feedbackMap(),recipes=(await allRecipes()).filter(r=>recipeAllowed(r,p)&&fb[r.id]!=='avoid');if(!recipes.length)throw new Error('No recipes match your current diet/exclusions.');const {data:recent}=await db.from('food_logs').select('recipe_id').not('recipe_id','is',null).order('logged_on',{ascending:false}).limit(30),recentCount={};(recent||[]).forEach(x=>recentCount[x.recipe_id]=(recentCount[x.recipe_id]||0)+1);const mealsPerDay=Number(p.meals_per_day||3),target={calories:Number(p.calorie_target||1800)/mealsPerDay,protein:Number(p.protein_target_g||150)/mealsPerDay,carbs:Number(p.carb_limit_g||150)/mealsPerDay},n=Number(plan.meals_to_cover||12),mode=plan.meal_prep_mode||'some',pattern=['Dinner','Lunch','Dinner','Breakfast','Lunch','Dinner','Breakfast','Lunch','Dinner','Snack'],chosen=[],counts={},ingredientUse={};function score(r,type){const macro=fitScore(r,target),typePenalty=(r.meal_types||[]).includes(type)?0:.45,pantryBonus=pantryCoverage(r,pantry)*.65,fav=fb[r.id]==='favorite'?-.35:fb[r.id]==='again'?-.15:0,history=(recentCount[r.id]||0)*.18,overlap=(r.recipe_ingredients||[]).filter(i=>ingredientUse[i.food_id]).length*.08;return macro+typePenalty+history-pantryBonus-fav-overlap}function pick(type){let pool=[...recipes].sort((a,b)=>score(a,type)-score(b,type));if(mode==='none')return pool.find(r=>!counts[r.id])||pool[0];if(mode==='batch'){const rep=pool.find(r=>(counts[r.id]||0)>0&&(counts[r.id]||0)<3);return rep||pool.find(r=>!counts[r.id])||pool[0]}if(chosen.length%3===1){const rep=pool.find(r=>(counts[r.id]||0)===1);if(rep)return rep}return pool.find(r=>!counts[r.id])||pool[0]}
 for(let i=0;i<n;i++){const r=pick(pattern[i%pattern.length]);chosen.push(r);counts[r.id]=(counts[r.id]||0)+1;(r.recipe_ingredients||[]).forEach(x=>ingredientUse[x.food_id]=1)}await db.from('weekly_meals').delete().eq('user_id',s.user.id).eq('week_start',plan.week_start);await db.from('weekly_meals').insert(chosen.map((r,i)=>({user_id:s.user.id,week_start:plan.week_start,slot_number:i+1,recipe_id:r.id,portion:1})));await db.from('weekly_plans').upsert({...plan,user_id:s.user.id,shopping_defined:true,updated_at:new Date().toISOString()},{onConflict:'user_id,week_start'});const meals=await weeklyMeals(plan.week_start);await rebuildGroceries(plan.week_start,meals);return meals}
async function setFeedback(recipeId,rating){const s=await session();await db.from('recipe_feedback').upsert({user_id:s.user.id,recipe_id:Number(recipeId),rating,updated_at:new Date().toISOString()},{onConflict:'user_id,recipe_id'})}
async function recipeBrowser(p){const all=(await allRecipes()).filter(r=>recipeAllowed(r,p));shell(`<div class="hero colorful"><span class="eyebrow">100+ RECIPES</span><h1>Recipe Library</h1><p>Find something by meal, time, diet, or protein.</p></div><div class="card"><input id="recipeSearch" placeholder="Search recipes or ingredients"><div class="filterRow"><button class="small secondary" data-filter="All">All</button><button class="small secondary" data-filter="Breakfast">Breakfast</button><button class="small secondary" data-filter="Lunch">Lunch</button><button class="small secondary" data-filter="Dinner">Dinner</button><button class="small secondary" data-filter="Snack">Snack</button></div></div><div id="browserResults"></div><button id="browserBack" class="secondary">Back to Eat</button>`,p.sex,'Eat');let filter='All';const draw=()=>{const q=(recipeSearch.value||'').toLowerCase(),xs=all.filter(r=>(filter==='All'||(r.meal_types||[]).includes(filter))&&(!q||r.name.toLowerCase().includes(q)||(r.tags||[]).join(' ').toLowerCase().includes(q)||(r.recipe_ingredients||[]).some(i=>i.foods?.name?.toLowerCase().includes(q))));browserResults.innerHTML=xs.slice(0,60).map((r,i)=>recipeCard(r,i,false)).join('')||'<div class="emptyState">No matches.</div>';browserResults.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>showRecipe(p,b.dataset.recipe,'Eat'))};recipeSearch.oninput=draw;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;draw()});browserBack.onclick=()=>eatView(p);draw()}
async function eatView(p,date=today()){const target=await ensureDailyTarget(p,date),{data:logs}=await db.from('food_logs').select('*').eq('logged_on',date).order('created_at'),ws=weekStart(),{data:plan}=await db.from('weekly_plans').select('*').eq('week_start',ws).maybeSingle(),meals=plan?.locked_at?await weeklyMeals(ws):[],prepped=await preparedMeals(),sum=k=>(logs||[]).reduce((a,x)=>a+Number(x[k]||0),0),used={calories:sum('calories'),protein:sum('protein_g'),carbs:sum('carbs_g'),fat:sum('fat_g')},remaining={calories:(target?.calories||0)-used.calories,protein:(target?.protein_g||0)-used.protein,carbs:(target?.carbs_g||0)-used.carbs,fat:(target?.fat_g||0)-used.fat};const ranked=[...meals].sort((a,b)=>Math.abs(recipeMacros(a.recipes).calories-Math.max(0,remaining.calories))-Math.abs(recipeMacros(b.recipes).calories-Math.max(0,remaining.calories)));const prepHtml=prepped.map((x,i)=>`<div class="readyMeal">${recipeVisual(x.recipes,'readyThumb')}<div><b>${x.recipes.name}</b><span>${x.portions_remaining} portion${Number(x.portions_remaining)===1?'':'s'} ready • made ${x.prepared_on}</span><small>${macroLine(recipeMacros(x.recipes))}</small></div><button data-eatprep="${i}">Eat one</button></div>`).join('');shell(`<div class="hero colorful"><span class="eyebrow">EAT • EXECUTE</span><h1>What's good right now?</h1><p>${Math.max(0,Math.round(remaining.calories))} calories • ${Math.max(0,Math.round(remaining.protein))}g protein remaining today.</p></div><div class="card macroCard">${macroStat('Calories',used.calories,target?.calories,'kcal')}${macroStat('Protein',used.protein,target?.protein_g,'g')}${macroStat('Carbs',used.carbs,target?.carbs_g,'g')}${macroStat('Fat',used.fat,target?.fat_g,'g')}</div><div class="card actionStrip"><button id="finishDay">Finish My Day</button><button id="browseRecipes" class="secondary">Browse recipes</button></div>${prepped.length?`<div class="sectionTitle"><div><span class="eyebrow">READY TO EAT</span><h2>Prepared meals</h2></div></div><div class="card">${prepHtml}</div>`:''}<div class="sectionTitle"><div><span class="eyebrow">PLANNED</span><h2>${ranked.length?`${ranked.length} meals this week`:'No locked week'}</h2></div></div>${ranked.map((w,i)=>recipeCard(w,i,false).replace('</div></div>',`<div class="recipeActions"><button data-eatmeal="${i}">I ate this</button></div></div></div>`)).join('')||'<div class="emptyState"><b>Lock a week in Shop.</b></div>'}<div class="card"><h2>Today’s log</h2>${renderLogs(logs)}</div>`,p.sex,'Eat');browseRecipes.onclick=()=>recipeBrowser(p);finishDay.onclick=()=>{const candidates=[...prepped.map(x=>({r:x.recipes,label:'Prepared'})),...ranked.map(x=>({r:x.recipes,label:'Planned'}))].sort((a,b)=>{const ma=recipeMacros(a.r),mb=recipeMacros(b.r);return Math.abs(ma.calories-Math.max(0,remaining.calories))+2*Math.abs(ma.protein-Math.max(0,remaining.protein))-(Math.abs(mb.calories-Math.max(0,remaining.calories))+2*Math.abs(mb.protein-Math.max(0,remaining.protein)))});if(candidates[0])alert(`Best fit: ${candidates[0].r.name}\n${macroLine(recipeMacros(candidates[0].r))}`);else alert('No planned or prepared meals available yet.')};document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>showRecipe(p,b.dataset.recipe,'Eat'));document.querySelectorAll('[data-eatmeal]').forEach(b=>b.onclick=async()=>{const w=ranked[Number(b.dataset.eatmeal)],r=w.recipes,m=recipeMacros(r),s=await session();await db.from('food_logs').insert({user_id:s.user.id,logged_on:date,meal_slot:(r.meal_types||[])[0]||'Other',recipe_id:r.id,item_name:r.name,servings:1,calories:m.calories,protein_g:m.protein,carbs_g:m.carbs,fat_g:m.fat});await consumeRecipe(r,1);eatView(p,date)});document.querySelectorAll('[data-eatprep]').forEach(b=>b.onclick=async()=>{const x=prepped[Number(b.dataset.eatprep)],r=x.recipes,m=recipeMacros(r),s=await session();await db.from('food_logs').insert({user_id:s.user.id,logged_on:date,meal_slot:(r.meal_types||[])[0]||'Other',recipe_id:r.id,item_name:r.name,servings:1,calories:m.calories,protein_g:m.protein,carbs_g:m.carbs,fat_g:m.fat});await db.from('prepared_meals').update({portions_remaining:Number(x.portions_remaining)-1}).eq('id',x.id);eatView(p,date)})}
async function showRecipe(p,id,back='Eat'){const rs=await allRecipes(),r=rs.find(x=>x.id===Number(id));if(!r)return;const m=recipeMacros(r),methods=r.cooking_methods||{},first=Object.keys(methods)[0],fb=await feedbackMap();shell(`<div class="hero recipeHero">${recipeVisual(r,'recipeHeroPhoto')}<div class="mealTypes">${(r.meal_types||[]).map(x=>`<span class="typeChip">${x.toUpperCase()}</span>`).join('')}${(r.tags||[]).slice(0,4).map(x=>`<span class="dietChip">${String(x).replaceAll('-',' ').toUpperCase()}</span>`).join('')}</div><h1>${r.name}</h1><p>${r.description||''}</p><div class="macroPills"><span>${Math.round(m.calories)} kcal</span><span>${Math.round(m.protein)}g protein</span><span>${Math.round(m.carbs)}g carbs</span><span>${Math.round(m.fat)}g fat</span></div></div><div class="card feedbackBar"><b>Would you eat this again?</b><div><button data-rate="favorite">♥ Favorite</button><button data-rate="again" class="secondary">👍 Yes</button><button data-rate="avoid" class="secondary">👎 Don't suggest</button></div><small>${fb[r.id]?`Current: ${fb[r.id]}`:'This helps future weekly plans.'}</small></div><div class="card"><h2>Ingredients</h2><div id="scaledIngredients">${r.recipe_ingredients.map(i=>`<div class="ingredient"><b>${i.foods.name}</b><span>${practicalAmount(i.foods.name,i.quantity_g)}</span></div>`).join('')}</div><label>Servings to make<select id="recipeServings"><option>1</option><option>2</option><option>3</option><option>4</option><option>6</option></select></label></div><div class="card"><h2>Choose how you're cooking</h2><div class="methodTabs">${methodButtons(methods)}</div></div><div id="cookMethod">${renderMethod(r,first)}</div><div class="card"><h2>Meal prep & leftovers</h2><p><b>Storage:</b> ${r.storage_instructions||''}</p><p><b>Reheating:</b> ${r.reheating_instructions||''}</p><button id="savePrep">I cooked these servings</button><p id="prepMsg"></p></div><button id="recipeBack" class="secondary">Back</button>`,p.sex,back);recipeServings.onchange=()=>{const mult=Number(recipeServings.value);scaledIngredients.innerHTML=r.recipe_ingredients.map(i=>`<div class="ingredient"><b>${i.foods.name}</b><span>${practicalAmount(i.foods.name,Number(i.quantity_g)*mult)}</span></div>`).join('')};document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-method]').forEach(x=>x.classList.remove('active'));b.classList.add('active');cookMethod.innerHTML=renderMethod(r,b.dataset.method)});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=async()=>{await setFeedback(r.id,b.dataset.rate);b.textContent='Saved ✓'});savePrep.onclick=async()=>{const s=await session(),n=Number(recipeServings.value||1);await consumeRecipe(r,n);const {error}=await db.from('prepared_meals').insert({user_id:s.user.id,recipe_id:r.id,prepared_on:today(),portions_prepared:n,portions_remaining:n});prepMsg.textContent=error?error.message:`${n} prepared portion${n===1?'':'s'} saved ✓`};recipeBack.onclick=()=>back==='Shop'?shopView(p):eatView(p)}

// ===== v0.8.1 — pricing, pantry visibility, and daily meal plans =====
function addDaysISO(dateStr,n){const d=new Date(dateStr+'T12:00:00');d.setDate(d.getDate()+Number(n||0));return d.toISOString().slice(0,10)}
function dayLabel(dateStr){const d=new Date(dateStr+'T12:00:00');return new Intl.DateTimeFormat(undefined,{weekday:'long',month:'short',day:'numeric'}).format(d)}
function packageGrams(q,u='g'){q=Number(q||0);u=String(u||'g').toLowerCase();if(u==='kg')return q*1000;if(['oz','ounce','ounces'].includes(u))return q*28.3495;if(['lb','lbs','pound','pounds'].includes(u))return q*453.592;return q}
function estimateFromInputs(need,price,pack){need=Number(need||0);price=Number(price||0);pack=Number(pack||0);if(!price||!pack)return null;return Math.ceil(need/pack)*price}
function normalizeSlots(slots){const allowed=['Breakfast','Lunch','Snack','Dinner'];const arr=(slots||[]).filter(x=>allowed.includes(x));return arr.length?arr:['Breakfast','Lunch','Snack','Dinner']}
function slotShares(slots){const base={Breakfast:.25,Lunch:.30,Snack:.15,Dinner:.30};const total=slots.reduce((a,x)=>a+(base[x]||.25),0)||1;const out={};slots.forEach(x=>out[x]=(base[x]||.25)/total);return out}
function planTargets(p){return {calories:Number(p.calorie_target||1800),protein:Number(p.protein_target_g||150),carbs:Number(p.carb_limit_g??150),fat:Number(p.fat_target_g||0)}}
function plannedMacros(meals){return meals.reduce((a,w)=>{const m=recipeMacros(w.recipes);const portion=Number(w.portion||1);a.calories+=m.calories*portion;a.protein+=m.protein*portion;a.carbs+=m.carbs*portion;a.fat+=m.fat*portion;return a},{calories:0,protein:0,carbs:0,fat:0})}
function compactMacro(m){return `${Math.round(m.calories)} kcal · ${Math.round(m.protein)}P · ${Math.round(m.carbs)}C · ${Math.round(m.fat)}F`}

async function saveShelfPrice(foodId,storeId,price,packageQty){if(!storeId||!price||!packageQty)return {error:{message:'Choose a store and enter both price and package size.'}};const s=await session();return db.from('food_prices').insert({user_id:s.user.id,food_id:Number(foodId),store_id:Number(storeId),price:Number(price),package_quantity:Number(packageQty),package_unit:'g',purchased_on:today()})}

async function pantryView(p){
 const s=await session(),{data:items}=await db.from('pantry_items').select('*,foods(*)').order('updated_at',{ascending:false}),{data:foods}=await db.from('foods').select('*').order('name');
 const rows=(items||[]).filter(x=>Number(x.quantity||0)>0).sort((a,b)=>(a.foods?.name||'').localeCompare(b.foods?.name||''));
 shell(`<div class="hero colorful"><span class="eyebrow">SHOP • PANTRY</span><h1>What you already have</h1><p>Pantry ingredients now reduce the grocery list and get extra weight when FatBoySchlim builds your week.</p></div>
 <div class="shopTabs"><button id="tabPlan">Plan</button><button id="tabList">Grocery list</button><button class="active">Pantry</button></div>
 <div class="card"><h2>Add or update food</h2><div class="formgrid"><label>Food<input id="pantryFood" list="pantryFoods" placeholder="Search food"><datalist id="pantryFoods">${(foods||[]).map(f=>`<option value="${f.name}">`).join('')}</datalist></label><label>Quantity on hand (g)<input id="pantryAddQty" type="number" min="0" step="1" placeholder="e.g. 500"></label></div><button id="pantryAdd">Save to pantry</button><p id="pantryMsg" class="hint"></p></div>
 <div class="card"><div class="cardhead"><h2>Pantry</h2><span>${rows.length} foods</span></div>${rows.length?rows.map(x=>`<div class="pantryRow"><div><b>${x.foods?.name||'Food'}</b><small class="muted">${x.foods?.category||''}</small></div><label>Grams<input class="pantryQty" data-pantryqty="${x.id}" type="number" min="0" step="1" value="${Math.round(Number(x.quantity||0))}"></label><button class="small secondary" data-pantrysave="${x.id}">Save</button><button class="small secondary" data-pantryremove="${x.id}">Remove</button></div>`).join(''):`<div class="pantryEmpty">Your pantry is empty. Add what you already have before generating the week.</div>`}</div>`,p.sex,'Shop');
 tabPlan.onclick=()=>shopView(p,'plan');tabList.onclick=()=>shopView(p,'grocery');
 pantryAdd.onclick=async()=>{const f=(foods||[]).find(x=>x.name===pantryFood.value),q=Number(pantryAddQty.value||0);if(!f){pantryMsg.textContent='Choose a food from the list.';return}await db.from('pantry_items').upsert({user_id:s.user.id,food_id:f.id,quantity:q,unit:'g',updated_at:new Date().toISOString()},{onConflict:'user_id,food_id'});pantryView(p)};
 document.querySelectorAll('[data-pantrysave]').forEach(b=>b.onclick=async()=>{const id=b.dataset.pantrysave,input=document.querySelector(`[data-pantryqty="${id}"]`);await db.from('pantry_items').update({quantity:Number(input.value||0),updated_at:new Date().toISOString()}).eq('id',id);b.textContent='Saved ✓'});
 document.querySelectorAll('[data-pantryremove]').forEach(b=>b.onclick=async()=>{await db.from('pantry_items').delete().eq('id',b.dataset.pantryremove);pantryView(p)});
}

function dailyPlanHTML(meals,p,locked){
 const groups={};meals.forEach(w=>{const d=w.planned_date||'Unscheduled';(groups[d]||(groups[d]=[])).push(w)});const target=planTargets(p),order={Breakfast:0,Lunch:1,Snack:2,Dinner:3};
 return Object.keys(groups).sort().map(d=>{const xs=groups[d].sort((a,b)=>(order[a.meal_slot]??9)-(order[b.meal_slot]??9)),m=plannedMacros(xs);return `<div class="card dayPlan"><div class="dayHead"><div><span class="eyebrow">${d==='Unscheduled'?'UNSCHEDULED':dayLabel(d).toUpperCase()}</span><h2>${d==='Unscheduled'?'Older meal pool':dayLabel(d)}</h2></div><div class="dayTotals">${compactMacro(m)}<br><span class="muted">Target ${Math.round(target.calories)} kcal · ${Math.round(target.protein)}P</span></div></div>${xs.map(w=>`<div class="slotMeal"><div class="slotLabel">${(w.meal_slot||'MEAL').toUpperCase()}</div><div><b>${w.recipes.name}</b><small>${compactMacro(recipeMacros(w.recipes))}</small></div><div class="recipeActions">${!locked?`<button class="small replaceButton" data-swapid="${w.id}">Replace</button>`:''}<button class="small secondary" data-recipe="${w.recipes.id}">Recipe</button></div></div>`).join('')}</div>`}).join('');
}

async function generateWeek(p,plan){
 const s=await session(),pantry=await pantryMap(),fb=await feedbackMap(),all=(await allRecipes()).filter(r=>recipeAllowed(r,p)&&fb[r.id]!=='avoid');if(!all.length)throw new Error('No recipes match your current diet/exclusions.');
 const slots=normalizeSlots(plan.meal_slots),days=Number(plan.days_to_plan||7),shares=slotShares(slots),daily=planTargets(p),mode=plan.meal_prep_mode||'some';
 const {data:recent}=await db.from('food_logs').select('recipe_id').not('recipe_id','is',null).order('logged_on',{ascending:false}).limit(50),recentCount={};(recent||[]).forEach(x=>recentCount[x.recipe_id]=(recentCount[x.recipe_id]||0)+1);
 const chosen=[],counts={},ingredientUse={};
 function score(r,slot,daySoFar){const m=recipeMacros(r),sh=shares[slot]||1/slots.length,slotT={calories:daily.calories*sh,protein:daily.protein*sh,carbs:Math.max(1,daily.carbs*sh)};let x=Math.abs(m.calories-slotT.calories)/Math.max(1,slotT.calories)*2+Math.abs(m.protein-slotT.protein)/Math.max(1,slotT.protein)*1.4+Math.max(0,m.carbs-slotT.carbs)/slotT.carbs*.8;const typeOk=(r.meal_types||[]).includes(slot);if(!typeOk)x+=4;const pantryBonus=pantryCoverage(r,pantry)*1.35;const overlap=(r.recipe_ingredients||[]).filter(i=>ingredientUse[i.food_id]).length*.09;const history=(recentCount[r.id]||0)*.16;const favorite=fb[r.id]==='favorite'?.35:fb[r.id]==='again'?.15:0;const repeat=counts[r.id]||0;if(mode==='none'&&repeat)x+=8+repeat*2;if(mode==='some'&&repeat>=2)x+=6;if(mode==='batch'&&repeat>=3)x+=6;const projected={calories:daySoFar.calories+m.calories,protein:daySoFar.protein+m.protein,carbs:daySoFar.carbs+m.carbs};const usedShare=slots.slice(0,slots.indexOf(slot)+1).reduce((a,z)=>a+(shares[z]||0),0);x+=Math.abs(projected.calories-daily.calories*usedShare)/Math.max(1,daily.calories)*.7+Math.abs(projected.protein-daily.protein*usedShare)/Math.max(1,daily.protein)*.5;return x+history-pantryBonus-overlap-favorite}
 for(let d=0;d<days;d++){let daySoFar={calories:0,protein:0,carbs:0};for(const slot of slots){let pool=all.filter(r=>(r.meal_types||[]).includes(slot));if(!pool.length)pool=all;pool=[...pool].sort((a,b)=>score(a,slot,daySoFar)-score(b,slot,daySoFar));let r=pool[0];if(mode==='some'&&chosen.length%4===2){const reusable=pool.find(x=>(counts[x.id]||0)===1);if(reusable&&score(reusable,slot,daySoFar)<score(r,slot,daySoFar)+.45)r=reusable}if(mode==='batch'){const reusable=pool.find(x=>(counts[x.id]||0)>0&&(counts[x.id]||0)<3);if(reusable&&score(reusable,slot,daySoFar)<score(r,slot,daySoFar)+.7)r=reusable}const m=recipeMacros(r);daySoFar.calories+=m.calories;daySoFar.protein+=m.protein;daySoFar.carbs+=m.carbs;counts[r.id]=(counts[r.id]||0)+1;(r.recipe_ingredients||[]).forEach(i=>ingredientUse[i.food_id]=1);chosen.push({r,planned_date:addDaysISO(plan.week_start,d),meal_slot:slot})}}
 await db.from('weekly_meals').delete().eq('user_id',s.user.id).eq('week_start',plan.week_start);
 const rows=chosen.map((x,i)=>({user_id:s.user.id,week_start:plan.week_start,slot_number:i+1,recipe_id:x.r.id,portion:1,planned_date:x.planned_date,meal_slot:x.meal_slot}));const ins=await db.from('weekly_meals').insert(rows);if(ins.error)throw ins.error;
 await db.from('weekly_plans').upsert({...plan,user_id:s.user.id,meals_to_cover:rows.length,shopping_defined:true,updated_at:new Date().toISOString()},{onConflict:'user_id,week_start'});
 const meals=await weeklyMeals(plan.week_start);await rebuildGroceries(plan.week_start,meals);return meals;
}

