 shell(`<div class="hero colorful"><span class="eyebrow">EAT • ${dayLabel(date).toUpperCase()}</span><div class="todayPlanHero"><div><h1>Today's plan</h1><p>${Math.max(0,Math.round(remaining.calories))} calories and ${Math.max(0,Math.round(remaining.protein))}g protein remain based on what you've logged.</p></div><div class="plannedMacro"><b>Planned</b><br>${compactMacro(planned)}<br><span class="muted">Target ${Math.round(target?.calories||0)} kcal · ${Math.round(target?.protein_g||0)}P</span></div></div></div><div class="card macroCard">${macroStat('Calories',used.calories,target?.calories,'kcal')}${macroStat('Protein',used.protein,target?.protein_g,'g')}${macroStat('Carbs',used.carbs,target?.carbs_g,'g')}${macroStat('Fat',used.fat,target?.fat_g,'g')}</div><div class="datebar card"><button id="prev" class="tiny secondary">‹</button><input id="eatDate" type="date" value="${date}"><button id="next" class="tiny secondary">›</button></div>${dayMeals.length?cards:`<div class="emptyState"><b>No daily plan for ${dayLabel(date)}.</b><span>${plan?.locked_at?'This day may be outside your current plan.':'Build and lock a daily plan in Shop.'}</span><button id="goShop">Go to Shop</button></div>`}<div class="card actionStrip"><button id="finishDay">Finish My Day</button><button id="browseRecipes" class="secondary">Browse recipes</button></div>${prepped.length?`<div class="card"><div class="cardhead"><h2>Prepared & ready</h2><span>${prepped.reduce((a,x)=>a+Number(x.portions_remaining||0),0)} portions</span></div>${prepHtml}</div>`:''}<div class="card"><div class="cardhead"><h2>Today's log</h2><button id="manualToggle" class="small secondary">+ Log something else</button></div>${renderLogs(logs)}<div id="manualBox" class="hidden"><div class="formgrid"><label>Name<input id="foodName"></label><label>Meal<select id="slot"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option><option>Other</option></select></label><label>Calories<input id="logCal" type="number"></label><label>Protein g<input id="logPro" type="number"></label><label>Carbs g<input id="logCar" type="number"></label><label>Fat g<input id="logFat" type="number"></label></div><button id="addFood">Add</button></div></div>`,p.sex,'Eat');
 const shift=n=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);eatView(p,d.toISOString().slice(0,10))};prev.onclick=()=>shift(-1);next.onclick=()=>shift(1);eatDate.onchange=()=>eatView(p,eatDate.value);if(document.querySelector('#goShop'))goShop.onclick=()=>shopView(p,'plan');browseRecipes.onclick=()=>recipeBrowser(p);document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>showRecipe(p,b.dataset.recipe,'Eat'));
 document.querySelectorAll('[data-eatplan]').forEach(b=>b.onclick=async()=>{const w=dayMeals.find(x=>String(x.id)===String(b.dataset.eatplan));if(!w)return;const r=w.recipes,m=recipeMacros(r),s=await session();await db.from('food_logs').insert({user_id:s.user.id,logged_on:date,meal_slot:w.meal_slot||'Other',recipe_id:r.id,item_name:r.name,servings:1,calories:m.calories,protein_g:m.protein,carbs_g:m.carbs,fat_g:m.fat});await consumeRecipe(r,1);eatView(p,date)});
 document.querySelectorAll('[data-eatprep]').forEach(b=>b.onclick=async()=>{const x=prepped[Number(b.dataset.eatprep)],r=x.recipes,m=recipeMacros(r),s=await session();await db.from('food_logs').insert({user_id:s.user.id,logged_on:date,meal_slot:(r.meal_types||[])[0]||'Other',recipe_id:r.id,item_name:r.name,servings:1,calories:m.calories,protein_g:m.protein,carbs_g:m.carbs,fat_g:m.fat});await db.from('prepared_meals').update({portions_remaining:Number(x.portions_remaining)-1}).eq('id',x.id);eatView(p,date)});
