async function flexView(p){const plan=await activeTrainingPlan();if(!plan)return trainingSetupView(p);const ws=weekStart(),schedule=await ensureTrainingWeek(plan,ws),{data:sessions}=await db.from('workout_sessions').select('*').gte('session_date',ws).lte('session_date',addDaysISO(ws,6)).order('session_date'),todaySched=schedule.find(x=>x.scheduled_date===today()),todaySession=(sessions||[]).find(x=>x.session_date===today()&&!x.completed_at),completed=schedule.filter(x=>(sessions||[]).some(s=>s.schedule_id===x.id&&s.completed_at)).length,rate=schedule.length?Math.round(completed/schedule.length*100):0;const weekHtml=schedule.map(x=>{const ses=(sessions||[]).find(s=>s.schedule_id===x.id),state=ses?.completed_at?'Complete':ses?'Started':x.status==='skipped'?'Skipped':'Planned';return `<div class="workoutDay ${x.scheduled_date===today()?'todayWorkout':''}"><div><span>${dayLabel(x.scheduled_date)}</span><b>${x.rotation_key}</b><small>${rotationBlurb(x.rotation_key)}</small></div><div class="workoutState ${state.toLowerCase()}">${state}</div>${x.scheduled_date===today()?`<button data-start-sched="${x.id}">${ses?'Continue':'Start'}</button>`:''}</div>`}).join('');shell(`<div class="hero colorful"><span class="eyebrow">FLEX • ${String(plan.split_type).toUpperCase()}</span><h1>${goalLabel(plan.primary_goal)} training</h1><p>${plan.days_per_week} days/week · ${arr(plan.weak_points).length?`Priority: ${arr(plan.weak_points).join(', ')}`:'Balanced development'}.</p></div><div class="card"><div class="cardhead"><h2>This week</h2><button id="editTraining" class="small secondary">Edit plan</button></div><div class="adherenceBar"><span style="width:${rate}%"></span></div><p class="hint">${completed}/${schedule.length} scheduled workouts complete · ${rate}% adherence</p>${weekHtml||'<div class="emptyState">No sessions scheduled.</div>'}</div>${todaySched?`<div class="card workoutFocus"><span class="eyebrow">TODAY</span><h2>${todaySched.rotation_key}</h2><p>${rotationBlurb(todaySched.rotation_key)}</p><button id="startToday">${todaySession?'Continue workout':'Start workout'}</button></div>`:`<div class="card"><h2>Recovery day</h2><p class="muted">No workout is scheduled today. Your rotation continues on the next training day.</p></div>`}<div class="card"><h2>How this plan is being chosen</h2><p class="muted">Goal: <b>${goalLabel(plan.primary_goal)}</b>. ${arr(plan.weak_points).length?`Extra volume is biased toward ${arr(plan.weak_points).join(', ')}.`:'Volume is balanced across muscle groups.'} Suggested loads come from your own previous sets whenever possible; new exercises start with an effort target rather than a made-up weight.</p></div>`,p.sex,'Flex');editTraining.onclick=()=>trainingSetupView(p,plan);document.querySelectorAll('[data-start-sched]').forEach(b=>b.onclick=async()=>{const sc=schedule.find(x=>String(x.id)===String(b.dataset.startSched));let ses=(sessions||[]).find(x=>x.schedule_id===sc.id&&!x.completed_at);const id=ses?.id||await createWorkoutSession(plan,sc);liveWorkoutView(p,id)});if(document.querySelector('#startToday'))startToday.onclick=async()=>{const id=todaySession?.id||await createWorkoutSession(plan,todaySched);liveWorkoutView(p,id)}}
