// ===== v0.9.2 — clearer Flex controls + always-visible exercise prescriptions =====
function flexEffortTarget(plan,ex){
 const g=plan?.primary_goal||'recomposition';
 if(g==='strength'&&ex?.compound)return {rir:'2–3 RIR',effort:'Hard, never grinding',tempo:'2–1–1'};
 if(g==='muscle-gain')return {rir:'1–2 RIR',effort:'Hard with clean form',tempo:'2–1–1'};
 if(g==='fat-loss')return {rir:'2 RIR',effort:'Good–Hard',tempo:'2–1–1'};
 if(g==='general-fitness')return {rir:'2–3 RIR',effort:'Good',tempo:'2–1–1'};
 return {rir:'1–2 RIR',effort:'Good–Hard',tempo:'2–1–1'};
}
function flexPrescriptionSentence(x,plan){
 const ex=x.exercise_library||{}, t=flexEffortTarget(plan,ex), reps=x.rep_min===x.rep_max?`${x.rep_min} reps`:`${x.rep_min}–${x.rep_max} reps`;
 const load=x.suggested_weight?` Start around ${x.suggested_weight} ${plan?.weight_unit||'lb'}.`:` Choose a load that leaves ${t.rir}.`;
 return `Perform ${x.target_sets} working sets of ${reps}.${load} Rest about ${x.rest_seconds||75} seconds between working sets. Stop the set if form breaks down or pain appears.`;
}
