// ===== v1.0 — Integrated Weekly Coach + navigation polish =====
function navIconV1(x){return {Today:'⌂',Eat:'🍴',Shop:'🛒',Flex:'💪',Progress:'↗'}[x]||'•'}
function shell(content,sex='unspecified',active='Today'){
 const tabs=['Today','Eat','Shop','Flex','Progress'];
 app.innerHTML=`<div class="shell"><header><div><div class="brand">FatBoySchlim</div><div class="tag">${subtitle(sex)}</div></div><div class="headerActions"><button id="settingsHubBtn" class="iconBtn" aria-label="Settings" title="Settings">⚙</button><button id="logout" class="tiny secondary">Log out</button></div></header>${content}<nav class="nav">${tabs.map(x=>`<button data-nav="${x}" class="navbtn ${x===active?'active':''}"><span class="navIcon">${navIconV1(x)}</span><span class="navLabel">${x}</span></button>`).join('')}</nav></div>`;
 logout.onclick=async()=>{await db.auth.signOut();authView()};
 settingsHubBtn.onclick=async()=>settingsHub(await profile());
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
}
async function weightTrendV1(){
 const {data}=await db.from('weight_logs').select('weight_lb,logged_on').order('logged_on',{ascending:false}).limit(21);
 if(!data?.length)return {current:null,weekly:null,avg7:null};
 const rows=[...data].reverse(),current=Number(data[0].weight_lb),last7=rows.slice(-7),prev7=rows.slice(-14,-7),avg=a=>a.length?a.reduce((s,x)=>s+Number(x.weight_lb),0)/a.length:null,avg7=avg(last7),avgPrev=avg(prev7);
 return {current,avg7,weekly:avg7!=null&&avgPrev!=null?avg7-avgPrev:null};
}
async function coachSignalsV1(p){
 const review=await weeklyReviewData(p),wt=await weightTrendV1(),signals=[];
 const calTarget=Number(review.target?.calories||p.calorie_target||0),proTarget=Number(review.target?.protein_g||p.protein_target_g||0),calPct=calTarget&&review.avgCal?review.avgCal/calTarget:0,proPct=proTarget&&review.avgPro?review.avgPro/proTarget:0,workPct=review.planned?review.complete/review.planned:0;
 if(p.goal_type==='lose'&&wt.weekly!=null){
   if(wt.weekly<-2)signals.push({kind:'warn',title:'Weight is moving quickly',text:`Your recent 7-day average is about ${Math.abs(wt.weekly).toFixed(1)} lb lower than the prior week. Consider a slightly smaller deficit if energy or training suffers.`});
   else if(wt.weekly>-0.2&&calPct>.9)signals.push({kind:'warn',title:'Fat-loss trend is slow',text:'You are fairly close to the calorie target but the recent weight trend is flat. Hold another week or consider a small 100–150 kcal adjustment.'});
   else if(wt.weekly<-.2)signals.push({kind:'good',title:'Weight trend is moving',text:`Recent 7-day average changed ${wt.weekly.toFixed(1)} lb versus the prior week.`});
 }
 if(proTarget&&proPct&&proPct<.85)signals.push({kind:'warn',title:'Protein is the obvious gap',text:`Average protein is ${Math.round(review.avgPro)}g versus a ${Math.round(proTarget)}g target. Let meal swaps and snacks prioritize protein next week.`});
 else if(proPct>=.95)signals.push({kind:'good',title:'Protein consistency is strong',text:`Average protein is ${Math.round(proPct*100)}% of target.`});
 if(review.planned&&workPct<.7)signals.push({kind:'warn',title:'Training schedule may be too ambitious',text:`Completed ${review.complete} of ${review.planned} planned sessions. Fewer high-quality sessions may beat a plan you regularly miss.`});
 else if(review.planned&&workPct>=.85)signals.push({kind:'good',title:'Flex adherence is strong',text:`Completed ${review.complete} of ${review.planned} planned sessions.`});
 if(review.useSoon.length)signals.push({kind:'warn',title:'Use-soon pantry items',text:`Prioritize ${review.useSoon.slice(0,4).join(', ')} in the next plan.`});
 if(!signals.length)signals.push({kind:'good',title:'Build some data',text:'Log meals, weight and workouts for a full week and FatBoySchlim will start comparing the plan with what actually happened.'});
 return {review,wt,signals};
}
function coachStoryV1(c,p){
 const {review,wt}=c;let lead='Your week is taking shape.';let body='Keep logging consistently so the recommendations can respond to what actually happens.';
 if(wt.weekly!=null){lead=`Weight trend: ${wt.weekly>0?'+':''}${wt.weekly.toFixed(1)} lb vs prior 7-day average.`;body=`You averaged ${review.avgCal?Math.round(review.avgCal)+' kcal':'no calorie data'} and ${review.avgPro?Math.round(review.avgPro)+'g protein':'no protein data'}. ${review.planned?`You completed ${review.complete} of ${review.planned} planned workouts.`:'Set up Flex to add training adherence.'}`}
 return {lead,body};
}
