async function boot(){const p=await profile();if(!p?.onboarding_complete)return onboarding(p||{});dashboardV1(p)}
async function navigate(x){const p=await profile();if(x==='Today')dashboardV1(p);else if(x==='Eat')eatView(p);else if(x==='Shop')shopView(p);else if(x==='Flex')flexView(p);else progressV1(p)}
